{
  "matches": [
    {
      "id": "tool:conclude_blocked",
      "kind": "tool",
      "name": "conclude_blocked",
      "description": "Declare that part of the task cannot be completed as specified, after you have established why.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "blocker": {
            "type": "string",
            "description": "What cannot be done and why it cannot. Shown to the user."
          },
          "criterion_id": {
            "type": "string",
            "description": "Optional id of the acceptance criterion that cannot be met."
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "description": "What you ran or read that establishes the blocker. At least one must match a receipt from this turn.",
            "items": {
              "type": "object",
              "properties": {
                "command": {
                  "type": "string",
                  "description": "A command you ran this turn, exactly as it ran. A command that failed is evidence too."
                },
                "paths": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Files you read or wrote this turn."
                }
              }
            }
          }
        },
        "required": [
          "blocker",
          "evidence"
        ]
      }
    },
    {
      "id": "tool:await_user",
      "kind": "tool",
      "name": "await_user",
      "description": "Hand control back to the user with the task list still open, when what the current item needs next is something only they can give: their view on what you just…",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "step_id": {
            "type": "string",
            "description": "The task-list item that is waiting. Defaults to the list's current in_progress item."
          },
          "need": {
            "type": "string",
            "description": "One short line: what you need from the user before this item can go on, written to them. Not the options and not the substance — those go in your reply, or in ask when they are choices."
          }
        },
        "required": [
          "need"
        ]
      }
    },
    {
      "id": "tool:complete_step",
      "kind": "tool",
      "name": "complete_step",
      "description": "Record the evidence-backed completion of ONE step of an approved plan.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "step_id": {
            "type": "string",
            "description": "PREFERRED: the stable step_id of the task-list item this completes, e.g. \"plan_step_02\". Unlike a title or a number it survives retitles, insertions, and reordering, so cite it whenever the item has one."
          },
          "step": {
            "type": "string",
            "description": "Which plan step this completes — its title or number, matching the task list. Use only when the item has no step_id."
          },
          "step_index": {
            "type": "integer",
            "minimum": 1,
            "description": "Optional 1-based task-list item number. Use only when the item has no step_id; an index goes stale the moment a step is inserted above it."
          },
          "result": {
            "type": "string",
            "description": "What is now true or changed as a result of finishing this step."
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "description": "Proof the step is done. At least one item is required.",
            "items": {
              "type": "object",
              "properties": {
                "criterion_id": {
                  "type": "string",
                  "description": "The acceptance criterion this proof satisfies, as the plan renders it (e.g. \"c2\" from \"accept [c2]: ...\"). Cite it whenever the step has criteria: a command succeeding is not the same as a criterion being met, and the host records the proof against the criterion you name."
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "verification",
                    "review",
                    "diff",
                    "files",
                    "manual"
                  ],
                  "description": "verification = a command/test was run (command REQUIRED); review = a built-in review run completed and, after changes, inspected the latest changed result (the verdict/findings still apply separately); diff = a concrete code change (paths REQUIRED); files = files created/edited/inspected (paths REQUIRED); manual = a manual check."
                },
                "summary": {
                  "type": "string",
                  "description": "The evidence itself: the test result, what the diff does, or what was confirmed."
                },
                "command": {
                  "type": "string",
                  "description": "REQUIRED for verification evidence: the command as it actually ran (e.g. \"go test ./...\") — it is checked against this session's real command history."
                },
                "paths": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "REQUIRED for diff/files evidence: the files this evidence refers to, as the paths were passed to the tools that touched them."
                }
              },
              "required": [
                "kind",
                "summary"
              ]
            }
          },
          "notes": {
            "type": "string",
            "description": "Optional caveats, follow-ups, or anything deferred."
          }
        },
        "required": [
          "result",
          "evidence"
        ]
      }
    },
    {
      "id": "tool:update_goal",
      "kind": "tool",
      "name": "update_goal",
      "description": "Report this turn's disposition for the active goal.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "status": {
            "type": "string",
            "enum": [
              "continue",
              "complete",
              "blocked"
            ],
            "description": "continue = keep working autonomously; complete = the goal is fully done and verified; blocked = only the user can unblock."
          },
          "reason": {
            "type": "string",
            "description": "Short explanation. REQUIRED for continue and blocked; optional for complete."
          },
          "next_action": {
            "type": "string",
            "description": "Optional concrete next step. Recommended for continue so the host can guide the next turn."
          },
          "completion": {
            "type": "object",
            "description": "Your own account of the finished work.",
            "properties": {
              "verified": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Commands you ran as proof, as they actually ran. One that never ran, failed, or predates your latest change is recorded as an unbacked claim."
              },
              "unverified": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "What you did NOT verify. The host cannot infer what you skipped, so stating it is the only way it is known — and it never blocks completion."
              },
              "risks": {
                "type": "array",
                "items": {
                  "type": "string"
                },
                "description": "Known risks to carry forward."
              }
            }
          }
        },
        "required": [
          "status"
        ]
      }
    },
    {
      "id": "tool:read_only_task",
      "aliases": [
        "task:read_only_subagent"
      ],
      "kind": "tool",
      "name": "read_only_task",
      "description": "Spawn a read-only research sub-agent for a focused investigation.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "prompt": {
            "type": "string",
            "description": "What the read-only sub-agent should investigate. Be specific about the evidence or summary to return — the sub-agent does not see this conversation."
          },
          "description": {
            "type": "string",
            "description": "Short label for the read-only sub-task (3-7 words). Surfaced in the dispatch line so the user sees what's running."
          },
          "tools": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional read-only tool whitelist. Writer, installer, memory mutation, background job, and delegation tools are never exposed."
          },
          "max_steps": {
            "type": "integer",
            "description": "Optional cap on tool-call rounds. Defaults to half the parent's cap (min 5).",
            "minimum": 1
          },
          "model": {
            "type": "string",
            "description": "Optional model override for the sub-agent (a configured provider/model name)."
          },
          "effort": {
            "type": "string",
            "description": "Optional reasoning effort for the sub-agent (e.g. high, max)."
          }
        },
        "required": [
          "prompt"
        ]
      }
    }
  ],
  "note": "Call action=call with a returned capability id. An empty matches array means this catalog search found no lexical match; it does not prove that every possible external capability is unavailable.",
  "query": "conclude blocked mark task impossible evidence"
}

